#- # routes.rb --- the routing table, from the model's URL shapes.
#- #
#- # This file IS a Rails routes file: the unmarked lines are the routes
#- # it generates, and the marked lines are the aontu that turns two
#- # entities into fifteen of them. `ruby -c` parses it as it stands.
#- @"../model.aon"
#-
#- out: file("config/routes.rb", [
#-   [
# Generated by `aontu render` from model.aon. Do not edit.
#
# The routes are written out rather than drawn with `resources`, because
# the API's paths are the reference's and not Rails' pluralised
# defaults: its collection is `/api/planet`, singular, and its
# parameter is `:planet_id` rather than `:id`.

Rails.application.routes.draw do
#-   ]
#-
#-   # THE ROOT PAGE. A one-element list of the value is how a body reads
#-   # a single fact out of the model: the dispatch binds `_` to it, and
#-   # `replace` puts it in the line.
#-   emit([$.service.root], {
#-     match: string
#-     replace: ROOT: _
#-     body: [
  root "ROOT"
#-     ]
#-   })
#-
#-   # --- the human pages -----------------------------------------------
#-   emit($.sequence, {
#-     match: controller: string
#-     # NO KEY IS A SUBSTRING OF ANOTHER, which `replace` checks before it
#-     # visits a node: `COLLECTION` inside `COLLECTION_HELPER` is refused
#-     # as `replace_overlap` rather than quietly rewriting half of it.
#-     replace: {
#-       UI_LIST: .ui_collection
#-       UI_ITEM: .ui_item
#-       CTRL: .controller
#-       HELPER_LIST: .ui_collection_helper
#-       HELPER_ITEM: .ui_item_helper
#-       TITLE: .plural
#-     }
#-     body: [

  # TITLE
  get "UI_LIST", to: "CTRL#index", as: :HELPER_LIST
  get "UI_ITEM", to: "CTRL#show", as: :HELPER_ITEM
#-     ]
#-   })
#-
#-   # --- the API -------------------------------------------------------
#-   # Five verbs every entity has, and then one POST per action it
#-   # declares. A moon declares none, so the inner dispatch emits nothing
#-   # and the file simply has no moon actions in it: the conditional IS
#-   # the selection.
#-   emit($.sequence, {
#-     match: controller: string
#-     replace: {
#-       API_LIST: .api_collection
#-       API_ITEM: .api_item
#-       CTRL: .controller
#-       TITLE: .plural
#-     }
#-     body: [

  # TITLE, the API
  get "API_LIST", to: "api/CTRL#index"
  post "API_LIST", to: "api/CTRL#create"
  get "API_ITEM", to: "api/CTRL#show"
  put "API_ITEM", to: "api/CTRL#update"
  delete "API_ITEM", to: "api/CTRL#destroy"
#-       emit(.action, {
#-         match: name: string
#-         replace: { API_PATH:.path ACTION:.name CTRL:.controller }
#-         body: [
  post "API_PATH", to: "api/CTRL#ACTION"
#-         ]
#-       })
#-     ]
#-   })
#-
#-   [
end
#-   ]
#- ])
